alter table public.workouts
  add column if not exists positions text[] not null default '{}',
  add column if not exists recommended_repetitions text not null default '3 rounds x 8 reps';

create index if not exists workouts_positions_idx on public.workouts using gin (positions);

insert into public.workouts
  (id,title,category,duration_minutes,difficulty,description,instructions,image_url,equipment_needed,positions,recommended_repetitions)
values
('a1f10001-0001-4a01-8a01-000000000001','First-Touch Gate','Dribbling',12,'Beginner','Settle the ball into your next action with a clean first touch.','Place two cones a metre apart as a gate. Pass the ball against a wall, receive across your body, and take your first touch through the gate. Alternate feet and reset after every pass.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['Football','2 cones'],array['ST','CF','LW','RW'],'4 sets x 8 receptions each foot'),
('a1f10001-0001-4a01-8a01-000000000002','Three-Zone Finishing','Agility',15,'Intermediate','Improve placement by aiming at specific areas instead of simply striking harder.','Mark three target zones in a goal or against a wall. From the edge of the area, take one setup touch and finish into a called zone. Retrieve the ball at a jog and change the angle every five shots.','https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=960&q=85',array['Football','4 markers'],array['ST','CF','LW','RW'],'5 sets x 6 shots; 2 per target zone'),
('a1f10001-0001-4a01-8a01-000000000003','Change-Pace 1v1','Dribbling',14,'Intermediate','Use a controlled feint and a sharp acceleration to beat an imaginary defender.','Set a defender cone five metres ahead and an exit gate two metres to either side. Approach under control, perform a shoulder drop or step-over, then accelerate through the opposite gate. Alternate sides.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=960&q=85',array['Football','3 cones'],array['ST','CF','LW','RW'],'4 sets x 5 attacks each side'),
('a1f10001-0001-4a01-8a01-000000000004','Blindside Movement Pattern','Agility',10,'Beginner','Practise moving away from a marker before checking into the ball.','Put a marker cone between you and the passing wall. Start close to the cone, step away as if losing your marker, then curve back into the passing lane. Receive on the half-turn and return the pass.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','1 cone','Wall'],array['ST','CF','LW','RW'],'3 sets x 8 check-away movements each side'),
('a1f10001-0001-4a01-8a01-000000000005','One-on-One Composure','Agility',15,'Advanced','Stay balanced, read the goalkeeper space, and finish with precision.','Carry the ball from 15 metres. At a marker, slow down for one controlled touch, choose a target corner, and finish with the inside or laces. Reset fully between efforts and alternate finishing feet.','https://images.unsplash.com/photo-1518091043644-c1d4457512c6?auto=format&fit=crop&w=960&q=85',array['Football','4 cones','Goal or target'],array['ST','CF','LW','RW'],'4 sets x 5 finishes per foot'),
('a1f10001-0001-4a01-8a01-000000000006','First-Five Acceleration','Stamina',12,'Beginner','Build a quicker first five metres with crisp, repeatable sprint starts.','Mark a five-metre start lane and a ten-metre finish. Begin from a football-ready stance, drive the first three steps powerfully, run through the finish, then walk back and recover fully.','https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=960&q=85',array['4 cones'],array['ST','CF','LW','RW'],'3 sets x 4 sprints; rest 45 seconds between reps'),

('a1f10001-0001-4a01-8a01-000000000007','Passing Range Ladder','Passing',14,'Beginner','Build weight and accuracy across short, medium, and long passes.','Mark targets at 3, 6, and 10 metres. Pass through each target in order, using the inside of both feet for short passes and a firm laces pass for distance. Reset your body between every pass.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=960&q=85',array['Football','6 cones','Wall'],array['CM','CDM','CAM','LM','RM'],'4 rounds x 3 passes at each distance per foot'),
('a1f10001-0001-4a01-8a01-000000000008','Through-Ball Window','Passing',15,'Intermediate','Pick the moment and weight to split a narrow defensive line.','Create two cone gates eight metres apart. Start behind a ball, scan over your shoulder, then play a through ball between the gates toward a marked target. Vary the approach angle and use both feet.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','4 cones'],array['CM','CDM','CAM','LM','RM'],'5 sets x 6 through balls; alternate feet'),
('a1f10001-0001-4a01-8a01-000000000009','Pressure-Box Receiving','Dribbling',12,'Intermediate','Protect your first touch while receiving inside a tight space.','Mark a 3-by-3-metre box. Pass against a wall, check both shoulders before the return, and control the ball inside the box. On alternate reps, take your second touch out of a different side.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['Football','4 cones','Wall'],array['CM','CDM','CAM','LM','RM'],'4 sets x 8 receptions; 30 seconds rest'),
('a1f10001-0001-4a01-8a01-000000000010','Shield and Escape','Dribbling',12,'Beginner','Keep the ball on the safe side, then escape into open space.','Place a cone as the defender and a second cone three metres away as the exit. Shield the ball with your body, roll it away with the sole, then accelerate through the exit. Switch your protecting side each rep.','https://images.unsplash.com/photo-1518091043644-c1d4457512c6?auto=format&fit=crop&w=960&q=85',array['Football','2 cones'],array['CM','CDM','CAM','LM','RM'],'3 sets x 6 escapes each side'),
('a1f10001-0001-4a01-8a01-000000000011','Half-Turn Wall Receive','Passing',10,'Beginner','Open your body before the ball arrives to play forward sooner.','Stand side-on to a wall with a marker just behind you. Check over your shoulder, pass firmly, and receive on the back foot so your next touch moves forward. Alternate which shoulder you check.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=960&q=85',array['Football','Wall','1 cone'],array['CM','CDM','CAM','LM','RM'],'4 sets x 8 half-turns each direction'),
('a1f10001-0001-4a01-8a01-000000000012','Four-Way Turn Matrix','Agility',13,'Intermediate','Turn away from pressure and accelerate into a new passing lane.','Set four gates around a central cone. Dribble into the centre, perform a Cruyff, inside hook, outside hook, or sole roll, then exit through the called gate. Reset the ball at the centre for each rep.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['Football','5 cones'],array['CM','CDM','CAM','LM','RM'],'4 rounds x 3 turns toward each gate'),
('a1f10001-0001-4a01-8a01-000000000013','Pressing Trigger Shadow','Stamina',14,'Advanced','Recognise a cue, close space under control, and block the forward lane.','Set a start cone and a target gate six metres away. Sprint on a visual cue, decelerate into a balanced defensive stance, and angle your approach to screen the gate. Walk back and reset before each start.','https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=960&q=85',array['4 cones'],array['CM','CDM','CAM','LM','RM'],'5 sets x 4 presses; rest 30 seconds between sets'),

('a1f10001-0001-4a01-8a01-000000000014','Front-Foot Interception','Agility',12,'Intermediate','Step into a passing lane at the right moment, then secure the ball.','Mark a passing lane with three cones. Start two metres away, shuffle laterally, then step forward across the lane and collect or intercept a rolled ball. Recover to your stance after every interception.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','3 cones'],array['CB','LB','RB'],'4 sets x 6 interceptions each direction'),
('a1f10001-0001-4a01-8a01-000000000015','Back-Line Shuffle and Drop','Agility',12,'Beginner','Stay side-on and protect the space behind you as play moves.','Set three cones in a shallow line. Move sideways between the first two in a low stance, then open your hips and drop back to the third. Face forward throughout and reset with controlled footwork.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['3 cones'],array['CB','LB','RB'],'4 sets x 5 shuffle-drop patterns each way'),
('a1f10001-0001-4a01-8a01-000000000016','Mirror Marking Footwork','Stamina',10,'Beginner','Match an attacker’s movement without crossing your feet.','Place two cones four metres apart. Shuffle between them while keeping your hips low and chest facing forward. Pause in a balanced stance at each cone, then return without crossing your legs.','https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=960&q=85',array['2 cones'],array['CB','LB','RB'],'4 sets x 20 seconds; rest 30 seconds between sets'),
('a1f10001-0001-4a01-8a01-000000000017','Block the Angle','Agility',12,'Intermediate','Close down space and set a strong body line to block the shot.','Place a ball six metres from a target. Start at an angle, close down with short steps, and plant your lead foot to cover the shooting line. Reset the ball and approach from alternating sides.','https://images.unsplash.com/photo-1518091043644-c1d4457512c6?auto=format&fit=crop&w=960&q=85',array['Football','4 cones','Target'],array['CB','LB','RB'],'4 sets x 6 block approaches from each side'),
('a1f10001-0001-4a01-8a01-000000000018','Jump and Head Clear','Stamina',12,'Beginner','Practise safe take-off, strong neck contact, and a balanced landing.','Toss a soft ball above forehead height. Jump from two feet, meet the ball with the forehead, and direct it forward into a clear zone. Land softly with knees bent. Use a partner only if available.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=960&q=85',array['Soft football'],array['CB','LB','RB'],'3 sets x 6 headers; reset fully between reps'),
('a1f10001-0001-4a01-8a01-000000000019','Split-Pass Build-Out','Passing',14,'Intermediate','Play out from the back with a purposeful first touch and accurate pass.','Set two gates at different angles, one short and one longer. Receive from a wall or partner, open your body on the first touch, and pass through the called gate. Alternate left and right passing lanes.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','5 cones','Wall'],array['CB','LB','RB'],'4 sets x 5 short and 5 long passes each foot'),
('a1f10001-0001-4a01-8a01-000000000020','Recovery Run and Turn','Stamina',14,'Advanced','Recover goal-side quickly, then turn into a controlled defensive stance.','Mark a five-metre recovery lane and a turn cone. Start facing forward, sprint back on a cue, look over your shoulder near the cone, then turn into a balanced stance. Walk back between efforts.','https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=960&q=85',array['3 cones'],array['CB','LB','RB'],'5 sets x 4 recovery runs; rest 40 seconds between sets'),

('a1f10001-0001-4a01-8a01-000000000021','Set, Move, Save','Agility',12,'Beginner','Reset your set position and move efficiently between low and high targets.','Start centred in a goal or marked area. Set your feet, take two quick side steps, and collect a rolled ball or touch a low target. Reset to centre before moving the other way. Keep your hands ready.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['Football','2 markers','Wall or partner'],array['GK'],'4 sets x 6 saves to each side'),
('a1f10001-0001-4a01-8a01-000000000022','Low-Dive Technique','Agility',12,'Beginner','Practise a safe low collapse dive with hands leading the ball.','Begin on one knee on a soft surface. Roll a ball just beyond your fingertips, push from the grounded foot, lead with both hands, and land on your side. Practise equally on each side before increasing distance.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','Soft training surface'],array['GK'],'3 sets x 5 low dives each side'),
('a1f10001-0001-4a01-8a01-000000000023','Catch, Set, Reset','Passing',10,'Beginner','Build secure handling and return to a balanced ready stance.','Toss a ball slightly above chest height. Catch with hands forming a W behind the ball, bring it into your body, reset your feet, and toss again. If alone, use a gentle wall rebound.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=960&q=85',array['Football','Wall optional'],array['GK'],'4 sets x 8 clean catches'),
('a1f10001-0001-4a01-8a01-000000000024','Goal-Line Positioning Arc','Agility',12,'Intermediate','Adjust your position with the ball while staying balanced and centred.','Place three markers across the goal line. Move along the arc between them as the ball moves from left to right, staying on the balls of your feet. Pause at each marker in a ready stance and return through centre.','https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=960&q=85',array['3 markers','Football'],array['GK'],'4 sets x 3 full side-to-side arcs'),
('a1f10001-0001-4a01-8a01-000000000025','Reaction Ball Wall','Agility',10,'Advanced','Improve first movement by reacting to an unpredictable rebound.','Stand two metres from a wall. Toss a small soft ball against it at varied angles, react to the rebound, and catch it before the second bounce. Keep your ready stance between each toss.','https://images.unsplash.com/photo-1518091043644-c1d4457512c6?auto=format&fit=crop&w=960&q=85',array['Reaction ball or soft ball','Wall'],array['GK'],'5 rounds x 30 seconds; rest 30 seconds'),
('a1f10001-0001-4a01-8a01-000000000026','Roll and Pass Distribution','Passing',12,'Intermediate','Release the ball accurately and find a target quickly after securing it.','Collect or pick up the ball, take one setup step, and roll it through a three-metre gate. Reset your stance, then repeat with a short overarm throw. Alternate target sides.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=960&q=85',array['Football','4 cones'],array['GK'],'4 sets x 6 rolls and 6 throws per side')
on conflict (id) do update set
  title = excluded.title,
  category = excluded.category,
  duration_minutes = excluded.duration_minutes,
  difficulty = excluded.difficulty,
  description = excluded.description,
  instructions = excluded.instructions,
  image_url = excluded.image_url,
  equipment_needed = excluded.equipment_needed,
  positions = excluded.positions,
  recommended_repetitions = excluded.recommended_repetitions;